  border-radius: 999px;
  color: white;
  text-decoration: none;
  font-size: 14px;
  backdrop-filter: blur(4px);
  transition: background 0.2s;
}
.hero-link:hover {
  background: rgba(255, 255, 255, 0.32);
}

