  border: 1px solid #bae6fd;
  border-radius: 10px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  color: #0c4a6e;
}
.banner-icon { font-size: 18px; }
.banner-meta { margin-left: 6px; color: #64748b; font-size: 12px; }
.banner-link { margin-left: auto; color: #2563eb; text-decoration: none; font-size: 13px; }
.banner-link:hover { text-decoration: underline; }

.theme-input-container {
  min-height: 100vh;
  background: linear-gradient(135deg, #f9fafb 0%, #ffffff 100%);
}

.hero-section {
